/**
 * Proxy: OHLC price history for a symbol
 * Proxy OHLC candlestick history from the Market Data Hub with local caching.
 *
 * Checks the local database cache first. If data is missing or incomplete,
 * fetches from the upstream Hub and updates the cache.
 *
 * Args:
 * symbol: Ticker symbol, e.g. ``AAPL`` or ``SPX``.
 * request: Incoming FastAPI request.
 * service: Market data service for DB access.
 * provider: Data provider identifier passed to the Hub.
 * interval: Candlestick interval, e.g. ``"1h"``, ``"4h"``, ``"1d"``.
 * start: ISO-8601 start datetime for the requested range (inclusive).
 * end: ISO-8601 end datetime for the requested range (inclusive).
 * sec_type: Optional security type hint, e.g. ``"index"``.
 *
 * Returns:
 * The JSON body with OHLC data.
 * @param data The data for the request.
 * @param data.symbol
 * @param data.provider
 * @param data.interval
 * @param data.start
 * @param data.end
 * @param data.secType
 * @returns OHLCResponse Successful Response
 * @throws ApiError
 */
export const getPriceHistoryApiV1MarketDataPricesSymbolHistoryGet = (data: GetPriceHistoryApiV1MarketDataPricesSymbolHistoryGetData): CancelablePromise<GetPriceHistoryApiV1MarketDataPricesSymbolHistoryGetResponse> => { return __request(OpenAPI, {
    method: 'GET',
    url: '/api/v1/market-data/prices/{symbol}/history',
    path: {
        symbol: data.symbol
    },
    query: {
        provider: data.provider,
        interval: data.interval,
        start: data.start,
        end: data.end,
        sec_type: data.secType
    },
    errors: {
        422: 'Validation Error'
    }
}); };

